net.coobird.thumbnailator.util.exif.IfdStructure ifdFalse = null;
net.coobird.thumbnailator.util.exif.IfdStructure ifdTrue = null;

// IfdStructure's constructor signature changed between versions (int vs IfdType enum for the type parameter).
// We use reflection to find the correct 4-argument constructor (tag, type, count, offsetValue) to instantiate it.
for (java.lang.reflect.Constructor<?> c : net.coobird.thumbnailator.util.exif.IfdStructure.class.getDeclaredConstructors()) {
    c.setAccessible(true);
    Class<?>[] params = c.getParameterTypes();
    if (params.length == 4) {
        try {
            if (params[1] == int.class) {
                // 3 = SHORT (2 bytes per element)
                ifdFalse = (net.coobird.thumbnailator.util.exif.IfdStructure) c.newInstance(0x0112, 3, 1, 8);
                ifdTrue = (net.coobird.thumbnailator.util.exif.IfdStructure) c.newInstance(0x0112, 3, 3, 8);
                break;
            } else if (params[1].isEnum()) {
                @SuppressWarnings({"unchecked", "rawtypes"})
                Object type = Enum.valueOf((Class<Enum>) params[1], "SHORT");
                ifdFalse = (net.coobird.thumbnailator.util.exif.IfdStructure) c.newInstance(0x0112, type, 1, 8);
                ifdTrue = (net.coobird.thumbnailator.util.exif.IfdStructure) c.newInstance(0x0112, type, 3, 8);
                break;
            }
        } catch (Exception e) {
            // Ignore and try next constructor
        }
    }
}

if (ifdFalse == null || ifdTrue == null) {
    throw new AssertionError("Could not instantiate IfdStructure to test isOffset()");
}

// Exercise the API
boolean resFalse = ifdFalse.isOffset();
boolean resTrue = ifdTrue.isOffset();

// Verify the result:
// Exif IFD values <= 4 bytes are stored inline (isOffset = false).
// Values > 4 bytes are stored elsewhere, and the value field is a pointer (isOffset = true).
// SHORT is 2 bytes. Count 1 = 2 bytes (inline). Count 3 = 6 bytes (offset).
assert !resFalse : "Expected isOffset to be false for 2-byte payload (<= 4 bytes)";
assert resTrue : "Expected isOffset to be true for 6-byte payload (> 4 bytes)";

System.out.println("__CHECK__ isOffset " + resFalse + "_" + resTrue);
